  function compare(op, actual, target) {
    switch (op) {
      case '==': return isNil(actual) && isNil(target) ? true : actual === target;
      case '!=': return !(isNil(actual) && isNil(target) ? true : actual === target);
      default: break;
    }
    if (isNil(actual) || isNil(target)) return false;
    if (Number.isNaN(actual) || Number.isNaN(target)) return false;
    switch (op) {
      case '>': return actual > target;
      case '>=': return actual >= target;
      case '<': return actual < target;
      case '<=': return actual <= target;
      default: return false;
    }
  }

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Unexpected end of filter');
    if (tok.type === '(') {
      consume('(');
      const inner = parseOr();
      consume(')');
      return inner;
    }
    const fieldTok = consume('IDENT');
    const opTok = consume('OP');
    const valTok = consume();
