    if (peek() && peek().type === 'NOT') {
      consume('NOT');
      const inner = parseNot();
      return (evt) => !inner(evt);
    }
    return parsePrimary();
  }

  function parseAnd() {
    let left = parseNot();
    while (peek() && peek().type === 'AND') {
      consume('AND');
      const l = left;
      const r = parseNot();
      left = (evt) => l(evt) && r(evt);
    }
    return left;
  }

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'OR') {
      consume('OR');
      const l = left;
      const r = parseAnd();
      left = (evt) => l(evt) || r(evt);
    }
    return left;
  }

  const fn = parseOr();
  if (pos !== tokens.length) {
    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected trailing token ${tokens[pos].value}`);
  }
  return fn;
